def transform(grid):
    """Complete the shorter of two paired patterned bands with color 1."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [any(v != background for v in row) for row in grid]

    # Find contiguous horizontal bands of non-background pixels.
    bands = []
    r = 0
    while r < len(grid):
        if not active[r]:
            r += 1
            continue
        start = r
        while r < len(grid) and active[r]:
            r += 1
        bands.append((start, r))

    if len(bands) < 2:
        return out

    # The task pairs two bands of equal height. Select the pair with the
    # largest shared height; in these tasks the wider band is the reference
    # and the shorter band is completed.
    pairs = []
    for i in range(len(bands)):
        for j in range(i + 1, len(bands)):
            h1 = bands[i][1] - bands[i][0]
            h2 = bands[j][1] - bands[j][0]
            if h1 == h2:
                pairs.append((h1, i, j))
    if not pairs:
        return out
    _, i, j = max(pairs)
    a0, a1 = bands[i]
    b0, b1 = bands[j]

    def right_edge(band):
        s, e = band
        return max(c for rr in range(s, e) for c, v in enumerate(grid[rr])
                   if v != background)

    # Fill the panel that ends earlier, using the other panel as a template.
    if right_edge((a0, a1)) <= right_edge((b0, b1)):
        target0, source0 = a0, b0
    else:
        target0, source0 = b0, a0

    height = a1 - a0
    for k in range(height):
        tr, sr = target0 + k, source0 + k
        last = max((c for c, v in enumerate(grid[tr]) if v != background), default=-1)
        for c in range(last + 1, len(grid[tr])):
            if grid[sr][c] != background:
                out[tr][c] = 1
    return out
