def transform(grid):
    """Extend the shorter of two aligned patterned bands using color 1."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [any(v != background for v in row) for row in grid]

    # Locate contiguous non-background bands.
    bands = []
    r = 0
    while r < len(grid):
        if not active[r]:
            r += 1
            continue
        start = r
        while r < len(grid) and active[r]:
            r += 1
        bands.append((start, r))
    if len(bands) < 2:
        return out

    # The two patterned panels have matching heights.
    matches = [(bands[i], bands[j])
               for i in range(len(bands))
               for j in range(i + 1, len(bands))
               if bands[i][1] - bands[i][0] == bands[j][1] - bands[j][0]]
    if not matches:
        return out
    first, second = max(matches, key=lambda p: p[0][1] - p[0][0])

    def edge(band):
        a, b = band
        return max(c for rr in range(a, b) for c, value in enumerate(grid[rr])
                   if value != background)

    # The panel with the shorter overall extent is the one to be completed.
    if edge(first) < edge(second):
        target, source = first, second
    else:
        target, source = second, first

    t0, t1 = target
    s0, _ = source
    for offset in range(t1 - t0):
        tr, sr = t0 + offset, s0 + offset
        last = max((c for c, value in enumerate(grid[tr]) if value != background),
                   default=-1)
        # Continue only the missing rightward tail, following foreground
        # pixels of the corresponding row in the longer panel.
        for c in range(last + 1, len(grid[tr])):
            if grid[sr][c] != background:
                out[tr][c] = 1
    return out
