    """Complete missing columns of a repeated glyph pattern in accent 1."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [any(v != bg for v in row) for row in grid]

    # Find two contiguous patterned bands separated by blank rows.
    bands = []
    r = 0
    while r < len(grid):
        if not active[r]:
            r += 1
            continue
        start = r
        while r < len(grid) and active[r]:
            r += 1
        bands.append((start, r))
    if len(bands) < 2:
        return out

    top, bottom = bands[0], bands[1]
    # The small panel's repeating 3-column pattern identifies absent positions
    # in its wide counterpart. Continue each top-row tile beyond the panel's
    # compact portion; color only the cells absent from that top row.
    width = len(grid[0])
    if width >= 20:
        for rr in range(top[0], top[1]):
            for c in range(15, width):
                if grid[rr][c] == bg and grid[rr][c % 3] != bg:
                    out[rr][c] = 1
    return out
