def transform(grid):
    """Complete truncated rows in paired panels using the matching row."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    active = [any(value != background for value in row) for row in grid]

    # Locate foreground bands separated by all-background rows.
    bands = []
    r = 0
    while r < len(grid):
        if not active[r]:
            r += 1
            continue
        start = r
        while r < len(grid) and active[r]:
            r += 1
        bands.append((start, r))
    if len(bands) < 2:
        return out

    # Paired panels have matching heights; corresponding rows line up by offset.
    pairs = [(bands[i], bands[j])
             for i in range(len(bands))
             for j in range(i + 1, len(bands))
             if bands[i][1] - bands[i][0] == bands[j][1] - bands[j][0]]
    if not pairs:
        return out
    first, second = max(pairs, key=lambda pair: pair[0][1] - pair[0][0])

    for offset in range(first[1] - first[0]):
        r1, r2 = first[0] + offset, second[0] + offset
        end1 = max((c for c, value in enumerate(grid[r1]) if value != background), default=-1)
        end2 = max((c for c, value in enumerate(grid[r2]) if value != background), default=-1)
        # A substantial end discrepancy indicates a clipped continuation.
        if abs(end1 - end2) < 2:
            continue
        target, source, target_end, source_end = (
            (r1, r2, end1, end2) if end1 < end2 else (r2, r1, end2, end1)
        )
        for c in range(target_end + 1, source_end + 1):
            if grid[source][c] != background:
                out[target][c] = 1
    return out
