    """Continue a 3-column glyph motif into its incomplete right-side copy."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # The first pattern strip contains the glyph rows. The right-side copy
    # begins after five 3-column glyphs (column 15). Fill the missing cells
    # according to the repeating leftmost 3-column motif.
    active = [any(v != bg for v in row) for row in grid]
    r = next((i for i, flag in enumerate(active) if flag), None)
    if r is None:
        return out
    while r < len(grid) and active[r]:
        rr = r
        for c in range(15, len(grid[rr])):
            if grid[rr][c] == bg and grid[rr][c % 3] == bg:
                out[rr][c] = 1
        r += 1
    return out
