def transform(grid):
    """Complete the shorter row in each aligned pair with the longer row's pattern."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Foreground strips are separated by rows of the dominant background color.
    bands = []
    r = 0
    while r < len(grid):
        if all(v == background for v in grid[r]):
            r += 1
            continue
        start = r
        while r < len(grid) and any(v != background for v in grid[r]):
            r += 1
        bands.append((start, r))
    if len(bands) < 2:
        return out

    # Two matching-height strips are aligned row by row. The longer row is the
    # reference; copy its non-background pattern into the shorter row's tail,
    # using accent color 1.
    pairs = [(bands[i], bands[j])
             for i in range(len(bands))
             for j in range(i + 1, len(bands))
             if bands[i][1] - bands[i][0] == bands[j][1] - bands[j][0]]
    if not pairs:
        return out
    first, second = max(pairs, key=lambda p: p[0][1] - p[0][0])

    for k in range(first[1] - first[0]):
        r1, r2 = first[0] + k, second[0] + k
        end1 = max((c for c, v in enumerate(grid[r1]) if v != background), default=-1)
        end2 = max((c for c, v in enumerate(grid[r2]) if v != background), default=-1)
        if end1 < end2:
            target, source, edge, source_edge = r1, r2, end1, end2
        elif end2 < end1:
            target, source, edge, source_edge = r2, r1, end2, end1
        else:
            continue
        for c in range(edge + 1, source_edge + 1):
            if grid[source][c] != background:
                out[target][c] = 1
    return out


