def transform(grid):
    """Find repeated 3-column glyphs and color their missing duplicate pixels."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find the first pattern band.
    active = [any(v != background for v in row) for row in grid]
    first = next((r for r, flag in enumerate(active) if flag), None)
    if first is None:
        return out
    end = first
    while end < len(grid) and active[end]:
        end += 1

    # Each 3-cell motif is copied after the 15-column seed. Existing colored
    # cells in that copy are retained; missing motif cells become 1.
    for r in range(first, end):
        for c in range(15, len(grid[r])):
            motif_col = c % 3
            if grid[r][c] == background and grid[r][motif_col] == background:
                out[r][c] = 1
    return out


